 for row in o['records']:
  c,f,reason,cell,step,pulse,last_rate,last_position,maxjerk,observed,bound=row;progress=c==7;rate=o['r']if progress else o['w'][c];prior=o['b']if progress else o['alpha'][c];position=o['s']if progress else o['C'][c];target=min(1e-8,rate)if progress else 0.;
